const body = $input.first().json.body || $input.first().json;

const tenant_id = body.tenant_id;
const plano = body.plano || 'essencial';
const conversa_id = body.conversa_id;
const mensagem = body.mensagem || '';
const historico = body.historico_conversa || [];
const perfil_cliente = body.perfil_cliente || {};
const canal = body.canal || 'synapse_chat';

// Curto-circuito: se um humano já assumiu essa conversa (status/assignee
// vindo do Chatwoot), a Lyra fica muda — não reabre uma conversa que já
// foi escalada, mesmo que chegue mensagem nova do cliente nesse meio-tempo.
const ja_escalada = body.status_conversa === 'open' && !!body.assignee_id;

// Detecção de pedido explícito de humano — feita aqui, ANTES de chamar a
// Lyra Central, porque não depende de IA nenhuma e é mais rápida/barata.
// Lista de frases é heurística, não NLU — ajustar conforme aparecerem
// variações reais de uso que não caiam aqui.
const FRASES_PEDIDO_HUMANO = [
  'falar com humano', 'falar com atendente', 'falar com uma pessoa',
  'falar com alguem', 'quero um atendente', 'quero falar com atendente',
  'atendimento humano', 'transferir para atendente', 'transferir pra atendente',
  'nao quero falar com robo', 'nao quero falar com bot', 'quero uma pessoa real'
];
const mensagemNormalizada = mensagem
  .toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, ''); // remove acentos pra comparar
const pedido_explicito_humano = FRASES_PEDIDO_HUMANO.some(f => mensagemNormalizada.includes(f));

// ia_suggestion (não "modo") pra bater com o node "Modo Autónomo ou Sugestão?"
// original, que já checa exatamente esse campo — mantido sem alteração.
const ia_suggestion = plano === 'essencial';

return [{
  json: {
    tenant_id, plano, conversa_id, mensagem, historico, perfil_cliente, canal,
    ja_escalada, pedido_explicito_humano, ia_suggestion
  }
}];

return [{
  json: {
    ...$json,
    resposta: 'Claro! Vou te transferir para um atendente humano agora mesmo.',
    escalar: true,
    motivo_escalamento: 'Cliente pediu explicitamente para falar com um humano'
  }
}];

const mensagens = (($json.historico || []).slice(-10)).map(m => ({
  role: m.de === 'cliente' ? 'user' : 'assistant',
  content: m.txt
}));
mensagens.push({ role: 'user', content: $json.mensagem });

const corpo = {
  tenant_id: $env.LYRA_TENANT_ID,
  conversation_id: $json.conversa_id,
  messages: mensagens,
  context: {
    channel: $json.canal,
    perfil_cliente: $json.perfil_cliente
  },
  tools_available: [
    'gerenciar_cadastro', 'mecanismo_captura_lead', 'processar_pedido',
    'faturamento_expedicao', 'consultar_pedido', 'verificar_estoque'
  ]
};

return [{ json: { ...$json, corpo_requisicao: corpo } }];

function parseSSE(texto) {
  const blocos = texto.split(/\r?\n\r?\n/).filter(Boolean);
  let tokens = '';
  let functionCall = null;
  let finishReason = null;
  for (const bloco of blocos) {
    const linhas = bloco.split(/\r?\n/);
    let evento = null;
    let dadosTexto = '';
    for (const linha of linhas) {
      if (linha.startsWith('event:')) evento = linha.slice(6).trim();
      if (linha.startsWith('data:')) dadosTexto += linha.slice(5).trim();
    }
    if (!evento || !dadosTexto) continue;
    let dados;
    try { dados = JSON.parse(dadosTexto); } catch (e) { continue; }
    if (evento === 'token') tokens += (dados.text || '');
    if (evento === 'function_call') functionCall = dados;
    if (evento === 'done') finishReason = dados.finish_reason;
  }
  return { tokens, functionCall, finishReason };
}const meta = $node['Monta Requisição pro Lyra Central'].json;
const bruto = $input.first().json.data ?? $input.first().json.body ?? $input.first().json;
const texto = typeof bruto === 'string' ? bruto : JSON.stringify(bruto);
const { tokens, functionCall, finishReason } = parseSSE(texto);

return [{
  json: {
    ...meta,
    texto_resposta: tokens,
    function_call: functionCall,
    finish_reason: finishReason,
    tem_function_call: !!functionCall
  }
}];

const fc = $json.function_call;

// Ações de alto impacto (mexem em dinheiro/pedido) vão pro L3, que tem
// as validações extras (motivo obrigatório em cancelar/estornar, etc).
// O resto (consultas e cadastro) vai pro L2. Mesmo critério do L1 original.
const FUNCOES_L3 = ['processar_pedido', 'faturamento_expedicao'];
const camada = FUNCOES_L3.includes(fc.name) ? 'l3' : 'l2';

// nome_funcao/argumentos_funcao (não function_call.name/arguments) pra bater
// com "Chama L3"/"Chama L2" originais, que já leem exatamente esses campos.
return [{
  json: {
    ...$json,
    camada,
    nome_funcao: fc.name,
    argumentos_funcao: fc.arguments
  }
}];

const meta = $node['Decide L2 ou L3'].json;
const resultadoFuncao = $input.first().json;

const corpo = {
  tenant_id: $env.LYRA_TENANT_ID,
  conversation_id: meta.conversa_id,
  call_id: meta.function_call.call_id,
  result: resultadoFuncao
};

return [{ json: { ...meta, corpo_requisicao: corpo, resultado_funcao: resultadoFuncao } }];

function parseSSE(texto) {
  const blocos = texto.split(/\r?\n\r?\n/).filter(Boolean);
  let tokens = '';
  let functionCall = null;
  let finishReason = null;
  for (const bloco of blocos) {
    const linhas = bloco.split(/\r?\n/);
    let evento = null;
    let dadosTexto = '';
    for (const linha of linhas) {
      if (linha.startsWith('event:')) evento = linha.slice(6).trim();
      if (linha.startsWith('data:')) dadosTexto += linha.slice(5).trim();
    }
    if (!evento || !dadosTexto) continue;
    let dados;
    try { dados = JSON.parse(dadosTexto); } catch (e) { continue; }
    if (evento === 'token') tokens += (dados.text || '');
    if (evento === 'function_call') functionCall = dados;
    if (evento === 'done') finishReason = dados.finish_reason;
  }
  return { tokens, functionCall, finishReason };
}const meta = $node['Monta Tool-Result'].json;
const bruto = $input.first().json.data ?? $input.first().json.body ?? $input.first().json;
const texto = typeof bruto === 'string' ? bruto : JSON.stringify(bruto);
const { tokens } = parseSSE(texto);

const sucesso = meta.resultado_funcao?.sucesso !== false;

return [{
  json: {
    ...meta,
    resposta: tokens || 'Prontinho!',
    escalar: !sucesso,
    motivo_escalamento: sucesso ? null : (meta.resultado_funcao?.erro || 'Não consegui concluir essa ação')
  }
}];

return [{
  json: {
    ...$json,
    resposta: $json.texto_resposta || 'Não consegui gerar uma resposta agora.',
    escalar: false,
    motivo_escalamento: null
  }
}];
